export type ParsedExecuteWithdrawInstruction<
  TProgram extends string = typeof SYTHSTAKING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    manager: TAccountMetas[0];
    pool: TAccountMetas[1];
    stakeToken: TAccountMetas[2];
    receiptToken: TAccountMetas[3];
    strategy: TAccountMetas[4];
    poolStakeAta: TAccountMetas[5];
    strategyAta: TAccountMetas[6];
    associatedTokenProgram: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
  };
  data: ExecuteWithdrawInstructionData;
};

export function parseExecuteWithdrawInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteWithdrawInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      manager: getNextAccount(),
      pool: getNextAccount(),
      stakeToken: getNextAccount(),
      receiptToken: getNextAccount(),
      strategy: getNextAccount(),
      poolStakeAta: getNextAccount(),
      strategyAta: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getExecuteWithdrawInstructionDataDecoder().decode(instruction.data),
  };
}
